/*
 * The linker error "undefined reference to `rtc_fake_get_time_fake`"
 * and "undefined reference to `rtc_fake_set_time_fake`" indicates that
 * the test is attempting to use FFF (Fake Function Framework) to mock
 * functions named `rtc_fake_get_time` and `rtc_fake_set_time`.
 * The `DEFINE_FAKE_VALUE_FUNC` macro creates a global struct named
 * `FUNCTION_NAME_fake`. Therefore, to resolve the linker error, these
 * fake functions must be properly defined using the FFF macros.
 */

/*
 * Forward declarations for the functions that are being faked.
 * These functions would typically be part of a fake RTC driver or a test utility.
 * They are declared here so that `DEFINE_FAKE_VALUE_FUNC` can use their signatures.
 */
int rtc_fake_get_time(const struct device *dev, struct rtc_time *tm);
int rtc_fake_set_time(const struct device *dev, const struct rtc_time *tm);

/* Define fakes for the internal fake RTC driver functions */
DEFINE_FAKE_VALUE_FUNC(int, rtc_fake_get_time, const struct device *, struct rtc_time *);
DEFINE_FAKE_VALUE_FUNC(int, rtc_fake_set_time, const struct device *, const struct rtc_time *);

static const struct device *rtc_dev;
static struct rtc_time expected_time_for_get; /* Used by custom_rtc_fake_get_time */

/* Custom fake for rtc_fake_get_time to populate the output struct */
static int custom_rtc_fake_get_time(const struct device *dev, struct rtc_time *tm)
{
	ARG_UNUSED(dev);

	if (rtc_fake_get_time_fake.return_val == 0 && tm != NULL) {
		*tm = expected_time_for_get;
	}
	return rtc_fake_get_time_fake.return_val;
}

